-- Spoken-only RP for gestures and reactions. No *emote* output.
local _, addon = ...
local texts = addon.localeData.deDE.generalTexts
texts.RAISE = { gruppe = { "Eine Frage hätte ich noch.", "Darf ich dazu etwas anmerken?" }, ziel = { "%s: Darf ich dazu etwas anmerken?", "%s: Eine Frage hätte ich noch." } }
texts.RASP = { gruppe = { "Das war meine freundlichste Antwort.", "Mein gutes Benehmen hat Grenzen." }, ziel = { "%s: Mein gutes Benehmen hat Grenzen.", "%s: Das war meine freundlichste Antwort." } }
texts.READY = { gruppe = { "Alles vorbereitet. Ich warte auf Euer Zeichen.", "Die Ausrüstung sitzt und die Entscheidung steht." }, ziel = { "%s: Die Ausrüstung sitzt und die Entscheidung steht.", "%s: Alles vorbereitet. Ich warte auf Euer Zeichen." } }
texts.REAR = { gruppe = { "Das Pferd hält offenbar auch eine Rede.", "Ruhig, mein Freund. Der Weg bleibt uns erhalten." }, ziel = { "%s: Ruhig, mein Freund. Der Weg bleibt uns erhalten.", "%s: Das Pferd hält offenbar auch eine Rede." } }
texts.ROAR = { gruppe = { "Jetzt hört auch der letzte Gegner zu!", "Manche Herausforderungen verdienen ein Gebrüll." }, ziel = { "%s: Manche Herausforderungen verdienen ein Gebrüll.", "%s: Jetzt hört auch der letzte Gegner zu!" } }
texts.RUDE = { gruppe = { "An Höflichkeit mangelt es Euch nicht zufällig?", "Ich finde wenig Gefallen an diesem Benehmen." }, ziel = { "%s: Ich finde wenig Gefallen an diesem Benehmen.", "%s: An Höflichkeit mangelt es Euch nicht zufällig?" } }
texts.SCRATCH = { gruppe = { "Dieser ganze Staub juckt entsetzlich.", "Eine Rüstung hilft nicht gegen jeden kleinen Feind." }, ziel = { "%s: Eine Rüstung hilft nicht gegen jeden kleinen Feind.", "%s: Dieser ganze Staub juckt entsetzlich." } }
texts.SEXY = { gruppe = { "Ein wenig Selbstvertrauen schadet nicht.", "Heute werde ich mich wohl von meiner besten Seite zeigen." }, ziel = { "%s: Heute werde ich mich wohl von meiner besten Seite zeigen.", "%s: Ein wenig Selbstvertrauen schadet nicht." } }
texts.SHAKE = { gruppe = { "Nein, das bringt uns nicht weiter.", "Man muss nicht jeden Unsinn bestätigen." }, ziel = { "%s: Man muss nicht jeden Unsinn bestätigen.", "%s: Nein, das bringt uns nicht weiter." } }
texts.SHIMMY = { gruppe = { "Musik lässt sich auch ohne Kapelle hören.", "Die Schultern haben den Rhythmus gefunden." }, ziel = { "%s: Die Schultern haben den Rhythmus gefunden.", "%s: Musik lässt sich auch ohne Kapelle hören." } }
texts.SHIVER = { gruppe = { "Mir läuft es kalt den Rücken hinunter.", "Das liegt bestimmt nicht nur am Wetter." }, ziel = { "%s: Das liegt bestimmt nicht nur am Wetter.", "%s: Mir läuft es kalt den Rücken hinunter." } }
texts.SHOO = { gruppe = { "Fort mit Euch, hier gibt es nichts zu holen!", "Wir könnten etwas Ruhe gebrauchen." }, ziel = { "%s: Wir könnten etwas Ruhe gebrauchen.", "%s: Fort mit Euch, hier gibt es nichts zu holen!" } }
texts.SHY = { gruppe = { "So viel Aufmerksamkeit bin ich nicht gewohnt.", "Vielleicht reden wir erst über etwas Einfaches." }, ziel = { "%s: Vielleicht reden wir erst über etwas Einfaches.", "%s: So viel Aufmerksamkeit bin ich nicht gewohnt." } }
texts.SIGH = { gruppe = { "Manche Tage brauchen mehr Geduld als andere.", "Nun gut. Noch einmal von vorn." }, ziel = { "%s: Nun gut. Noch einmal von vorn.", "%s: Manche Tage brauchen mehr Geduld als andere." } }
texts.SLAP = { gruppe = { "Das sollte die Aufmerksamkeit zurückbringen.", "Eine Erinnerung mit etwas Nachdruck." }, ziel = { "%s: Eine Erinnerung mit etwas Nachdruck.", "%s: Das sollte die Aufmerksamkeit zurückbringen." } }
texts.SMELL = { gruppe = { "Irgendwo wird etwas sehr Gutes gekocht.", "Oder ist das etwa Rauch? Das wäre weniger gut." }, ziel = { "%s: Oder ist das etwa Rauch? Das wäre weniger gut.", "%s: Irgendwo wird etwas sehr Gutes gekocht." } }
texts.SMIRK = { gruppe = { "Ich weiß etwas, das Ihr noch nicht wisst.", "Ein kleines Geheimnis macht den Tag interessanter." }, ziel = { "%s: Ein kleines Geheimnis macht den Tag interessanter.", "%s: Ich weiß etwas, das Ihr noch nicht wisst." } }
texts.SNARL = { gruppe = { "Der nächste Schritt könnte ein Fehler sein.", "Manche Grenzen sollte niemand überschreiten." }, ziel = { "%s: Manche Grenzen sollte niemand überschreiten.", "%s: Der nächste Schritt könnte ein Fehler sein." } }
texts.SNICKER = { gruppe = { "Das war bestimmt nicht so geplant.", "Ich versuche wirklich, nicht zu lachen." }, ziel = { "%s: Ich versuche wirklich, nicht zu lachen.", "%s: Das war bestimmt nicht so geplant." } }
texts.SNIFF = { gruppe = { "Das riecht nach einer Geschichte.", "Meine Nase ist sich noch nicht sicher." }, ziel = { "%s: Meine Nase ist sich noch nicht sicher.", "%s: Das riecht nach einer Geschichte." } }
texts.SNUB = { gruppe = { "Heute habe ich auf dieses Gespräch keine Lust.", "Nicht jede Einladung verdient eine Antwort." }, ziel = { "%s: Nicht jede Einladung verdient eine Antwort.", "%s: Heute habe ich auf dieses Gespräch keine Lust." } }
texts.SOOTHE = { gruppe = { "Ganz ruhig, die Gefahr ist vorüber.", "Wir finden gemeinsam wieder festen Boden." }, ziel = { "%s: Wir finden gemeinsam wieder festen Boden.", "%s: Ganz ruhig, die Gefahr ist vorüber." } }
texts.SPIT = { gruppe = { "Diesen Geschmack werde ich nicht vermissen.", "Manches gehört einfach nicht in den Mund." }, ziel = { "%s: Manches gehört einfach nicht in den Mund.", "%s: Diesen Geschmack werde ich nicht vermissen." } }
texts.SPOON = { gruppe = { "Ein warmer Platz ist ein guter Anfang.", "Nähe macht den kalten Abend erträglicher." }, ziel = { "%s: Nähe macht den kalten Abend erträglicher.", "%s: Ein warmer Platz ist ein guter Anfang." } }
texts.STARE = { gruppe = { "Das verdient einen sehr langen Blick.", "Ich warte auf die vernünftige Erklärung." }, ziel = { "%s: Ich warte auf die vernünftige Erklärung.", "%s: Das verdient einen sehr langen Blick." } }
texts.STINK = { gruppe = { "Hier muss dringend gelüftet werden.", "Was immer dort liegt, es ist nicht mehr frisch." }, ziel = { "%s: Was immer dort liegt, es ist nicht mehr frisch.", "%s: Hier muss dringend gelüftet werden." } }
texts.STRONG = { gruppe = { "Gemeinsam halten wir mehr aus als allein.", "Stärke zeigt sich auch darin, anderen zu helfen." }, ziel = { "%s: Stärke zeigt sich auch darin, anderen zu helfen.", "%s: Gemeinsam halten wir mehr aus als allein." } }
texts.STRUT = { gruppe = { "Man muss sich auch einmal feiern dürfen.", "Der nächste Schritt verdient eine triumphale Haltung." }, ziel = { "%s: Der nächste Schritt verdient eine triumphale Haltung.", "%s: Man muss sich auch einmal feiern dürfen." } }
texts.SURRENDER = { gruppe = { "Ich lege die Waffen nieder. Für jetzt.", "Ein weiterer Kampf würde niemandem helfen." }, ziel = { "%s: Ein weiterer Kampf würde niemandem helfen.", "%s: Ich lege die Waffen nieder. Für jetzt." } }
texts.SURPRISED = { gruppe = { "Das stand nicht in unserer Planung.", "Man lernt offenbar nie aus." }, ziel = { "%s: Man lernt offenbar nie aus.", "%s: Das stand nicht in unserer Planung." } }
texts.TALK = { gruppe = { "Ein gutes Gespräch ist einen Umweg wert.", "Lasst uns erst reden, dann entscheiden." }, ziel = { "%s: Lasst uns erst reden, dann entscheiden.", "%s: Ein gutes Gespräch ist einen Umweg wert." } }
texts.TALKEX = { gruppe = { "Das meine ich vollkommen ernst!", "Manchmal muss ein Gedanke laut ausgesprochen werden." }, ziel = { "%s: Manchmal muss ein Gedanke laut ausgesprochen werden.", "%s: Das meine ich vollkommen ernst!" } }
texts.TALKQ = { gruppe = { "Könnt Ihr mir das noch einmal erklären?", "Ich möchte wirklich verstehen, was Ihr meint." }, ziel = { "%s: Ich möchte wirklich verstehen, was Ihr meint.", "%s: Könnt Ihr mir das noch einmal erklären?" } }
texts.TAP = { gruppe = { "Meine Geduld hat einen hörbaren Takt.", "Wer hat behauptet, Warten sei einfach?" }, ziel = { "%s: Wer hat behauptet, Warten sei einfach?", "%s: Meine Geduld hat einen hörbaren Takt." } }
texts.TAUNT = { gruppe = { "Kommt doch her, wenn Ihr Euch traut!", "Ich bin noch lange nicht fertig mit Euch." }, ziel = { "%s: Ich bin noch lange nicht fertig mit Euch.", "%s: Kommt doch her, wenn Ihr Euch traut!" } }
texts.TEASE = { gruppe = { "Das war nur ein kleiner Scherz auf Eure Kosten.", "Ein bisschen Necken hält Freunde wach." }, ziel = { "%s: Ein bisschen Necken hält Freunde wach.", "%s: Das war nur ein kleiner Scherz auf Eure Kosten." } }
texts.THIRSTY = { gruppe = { "Ein kühler Schluck wäre jetzt ein Segen.", "Mein Hals fühlt sich wie eine Wüste an." }, ziel = { "%s: Mein Hals fühlt sich wie eine Wüste an.", "%s: Ein kühler Schluck wäre jetzt ein Segen." } }
texts.THREAT = { gruppe = { "Ich warne Euch nur dieses eine Mal.", "Setzt meine Geduld nicht auf die Probe." }, ziel = { "%s: Setzt meine Geduld nicht auf die Probe.", "%s: Ich warne Euch nur dieses eine Mal." } }
texts.THREATEN = { gruppe = { "Der nächste Schritt wird Euch teuer zu stehen kommen.", "Meine Warnung war nicht zum Zeitvertreib." }, ziel = { "%s: Meine Warnung war nicht zum Zeitvertreib.", "%s: Der nächste Schritt wird Euch teuer zu stehen kommen." } }
texts.TICKLE = { gruppe = { "Auch ernste Helden haben Schwachstellen.", "Ein bisschen Gelächter kann Wunder wirken." }, ziel = { "%s: Ein bisschen Gelächter kann Wunder wirken.", "%s: Auch ernste Helden haben Schwachstellen." } }
texts.TIRED = { gruppe = { "Heute tragen meine Stiefel doppelte Last.", "Ich brauche eine Bank und keine weitere Aufgabe." }, ziel = { "%s: Ich brauche eine Bank und keine weitere Aufgabe.", "%s: Heute tragen meine Stiefel doppelte Last." } }
texts.TRAIN = { gruppe = { "Tschu tschuu! Aus dem Weg, der Zug kommt!", "Wer hat gesagt, Helden müssten immer ernst sein?" }, ziel = { "%s: Wer hat gesagt, Helden müssten immer ernst sein?", "%s: Tschu tschuu! Aus dem Weg, der Zug kommt!" } }
texts.VETO = { gruppe = { "Bei diesem Vorhaben erhebe ich entschiedenen Einspruch.", "Nicht jeder Plan wird besser, nur weil er laut ist." }, ziel = { "%s: Nicht jeder Plan wird besser, nur weil er laut ist.", "%s: Bei diesem Vorhaben erhebe ich entschiedenen Einspruch." } }
texts.VIOLIN = { gruppe = { "Ach, welch ein tragisches Schicksal.", "Soll ich eine besonders traurige Melodie spielen?" }, ziel = { "%s: Soll ich eine besonders traurige Melodie spielen?", "%s: Ach, welch ein tragisches Schicksal." } }
